/**
 * * Write a function to find the top k integers that occur most frequently from given lists of sorted and distinct integers using heap queue algorithm.
 *
 * > func([[1, 2, 6], [1, 3, 4, 5, 7, 8], [1, 3, 5, 6, 8, 9], [2, 5, 7, 11], [1, 4, 7, 8, 12]], 3)
 * [5, 7, 1]
 * > func([[1, 2, 6], [1, 3, 4, 5, 7, 8], [1, 3, 5, 6, 8, 9], [2, 5, 7, 11], [1, 4, 7, 8, 12]], 1)
 * [1]
 * > func([[1, 2, 6], [1, 3, 4, 5, 7, 8], [1, 3, 5, 6, 8, 9], [2, 5, 7, 11], [1, 4, 7, 8, 12]], 5)
 * [6, 5, 7, 8, 1]
 */
function func(nums, k) {
  const heap = new Heap((a, b) => b[1] - a[1]);
  for (let i = 0; i < nums.length; i++) {
    for (let j = 0; j < nums[i].length; j++) {
      if (heap.size() < k) {
        heap.push([nums[i][j], 1]);
      } else {
        const top = heap.peek();
        if (top[0] !== nums[i][j]) {
          heap.pop();
          heap.push([nums[i][j], 1]);
        } else {
          heap.updateTop(1);
        }
      }
    }
  }
  return heap.toArray().map(x => x[0]);
}
