/**
 * * Write a function to sort the given array by using counting sort.
 *
 * > countingSort([1, 23, 4, 5, 6, 7, 8])
 * [1, 4, 5, 6, 7, 8, 23]
 * > countingSort([12, 9, 28, 33, 69, 45])
 * [9, 12, 28, 33, 45, 69]
 * > countingSort([8, 4, 14, 3, 2, 1])
 * [1, 2, 3, 4, 8, 14]
 */
function countingSort(mylist) {
  const max = Math.max(...mylist);
  const min = Math.min(...mylist);
  const range = max - min + 1;
  const count = Array(range).fill(0);
  const result = [];

  for (let i = 0; i < mylist.length; i++) {
    count[mylist[i] - min]++;
  }

  for (let i = 1; i < count.length; i++) {
    count[i] += count[i - 1];
  }

  for (let i = mylist.length - 1; i >= 0; i--) {
    result[count[mylist[i] - min] - 1] = mylist[i];
    count[mylist[i] - min]--;
  }

  return result;
}
