 * > combSort([41, 32, 15, 19, 22])
 * [15, 19, 22, 32, 41]
 * > combSort([99, 15, 13, 47])
 * [13, 15, 47, 99]
 */
function combSort(nums) {
  let gap = nums.length;
  let swapped = true;

  while (gap > 1 || swapped) {
    if (gap > 1) {
      gap = Math.floor(gap / 1.3);
    }

    swapped = false;

    for (let i = 0; i + gap < nums.length; i++) {
      if (nums[i] > nums[i + gap]) {
        [nums[i], nums[i + gap]] = [nums[i + gap], nums[i]];
        swapped = true;
      }
    }
  }

  return nums;
}
