 * true
 * > isValidParenthese("()[{)}")
 * false
 * > isValidParenthese("()")
 * true
 */
function isValidParenthese(str1) {
  let stack = [];
  for (let i = 0; i < str1.length; i++) {
    if (str1[i] === "(" || str1[i] === "{" || str1[i] === "[") {
      stack.push(str1[i]);
    } else {
      if (stack.length === 0) {
        return false;
      }
      let last = stack.pop();
      if (
        (str1[i] === ")" && last !== "(") ||
        (str1[i] === "}" && last !== "{") ||
        (str1[i] === "]" && last !== "[")
      ) {
        return false;
      }
    }
  }
  return stack.length === 0;
}
