 *
 * > distanceLatLong(23.5, 67.5, 25.5, 69.5)
 * 12179.372041317429
 * > distanceLatLong(10.5, 20.5, 30.5, 40.5)
 * 6069.397933300514
 * > distanceLatLong(10, 20, 30, 40)
 * 6783.751974994595
 */
function distanceLatLong(slat, slon, elat, elon) {
  const R = 6371; // km
  const dLat = (elat - slat) * Math.PI / 180;
  const dLon = (elon - slon) * Math.PI / 180;
  const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(slat * Math.PI / 180) * Math.cos(elat * Math.PI / 180) *
    Math.sin(dLon / 2) * Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c;
}
