 *
 * > shellSort([12, 23, 4, 5, 3, 2, 12, 81, 56, 95])
 * [2, 3, 4, 5, 12, 12, 23, 56, 81, 95]
 * > shellSort([24, 22, 39, 34, 87, 73, 68])
 * [22, 24, 34, 39, 68, 73, 87]
 * > shellSort([32, 30, 16, 96, 82, 83, 74])
 * [16, 30, 32, 74, 82, 83, 96]
 */
function shellSort(mylist) {
  for (let gap = Math.floor(mylist.length / 2); gap > 0; gap = Math.floor(gap / 2)) {
    for (let i = gap; i < mylist.length; i++) {
      let temp = mylist[i];
      for (let j = i; j >= gap && mylist[j - gap] > temp; j -= gap) {
        mylist[j] = mylist[j - gap];
      }
      mylist[j] = temp;
    }
  }
  return mylist;
}
