 * [14, 22]
 * > heapQueueSmallest([25, 35, 22, 85, 14, 65, 75, 22, 58], 5)
 * [14, 22, 22, 25, 35]
 */
function heapQueueSmallest(nums, n) {
  const heap = new Heap((a, b) => a - b);
  for (let i = 0; i < n; i++) {
    heap.push(nums[i]);
  }
  const result = [];
  for (let i = 0; i < n; i++) {
    result.push(heap.pop());
  }
  return result;
}
