 * {"7":2,"8":2,"9":1,"10":1,"11":2}
 */
function countElementFreq(testtuple) {
  return testtuple.reduce((acc, curr) => {
    if (Array.isArray(curr)) {
      return { ...acc, ...countElementFreq(curr) };
    }
    return { ...acc, [curr]: (acc[curr] || 0) + 1 };
  }, {});
}
